Method.Implementation:
	s id=""
	s TCIndent=$ZConvert(TCIndentity,"U")
	s id=$o(^NurMp.TemplateI("TCIndentity"," "_TCIndent,id),-1)
	s a=##class(NurMp.Template).%OpenId(id)
	q:id="" ""
	s data=a.Content

	s base64str=""
	Set newstream=##class(%GlobalCharacterStream).%New()
	if (data.IsNull())
	{
		d newstream.Write("")
	}
	else
	{

   		Do data.Rewind() Set len=12000
    	While 'data.AtEnd {
      	;s base64str = $system.Encryption.Base64Encode(data.Read(.len),1)
      	s base64str=##class(%SYSTEM.Encryption).Base64Encode(data.Read(.len))
      	d newstream.Write(base64str)
    	}
	}
	q newstream

//q "D:\DTHealth\app\dthis\web\scripts\bdp\Framework\Doc\"

if AppPath = ""{

	Set App="/dthealth/web"
}Else{
	Set App = AppPath
}

Set dir=""
Set CurNS=$namespace
zn "%sys"
if $d(^SYS("Security","ApplicationsD",App),g){
	Set dir = $lg(g,17)
}else{
	Set App1 = $p(App,"/",1,$l(App,"/")-1)

	if $d(^SYS("Security","ApplicationsD","/dthealth/web"),g){
		Set dir = $lg(g,17)_"/"_$p(App,"/",$l(App,"/"))
	}else{
		Set App2 = $p(App,"/",1,$l(App,"/")-2)
