}

	s code=$zcvt(indentity,"U")
	q:code="" -99
	i $d(^NurMP.NurEmrSubLock("Mp",code))
	{
		s nowtime=$h
		s ^NurMP.NurEmrSubLock("Mp",code) = $p(^NurMP.NurEmrSubLock("Mp",code),"^",1)_"^"_$p(^NurMP.NurEmrSubLock("Mp",code),"^",2)_"^"_nowtime_"^"_$p(^NurMP.NurEmrSubLock("Mp",code),"^",4)
	}

	//遍历^NurEmr.NurEmrSubLock，把35分钟内没有心跳的节点kill

	s code = ""
	s nowtime=$p($h,",",1)+$p($h,",",2)

	for{
		s code = $o(^NurMP.NurEmrSubLock("Mp",code))
		q:code=""
		s hearttime = $p(^NurMP.NurEmrSubLock("Mp",code),"^",3)
		//s ^yucz(code_nowtime) = code_"--"_nowtime
		if ((hearttime[",")&&($ZABS(nowtime - $p(hearttime,",",1)-$p(hearttime,",",2)) > (35*60)))
		{
			k ^NurMP.NurEmrSubLock("Mp",code)
		}
		elseif (hearttime'[",")&&(($ZABS($p($h,",",2) - hearttime) > (35*60)))
		{
             k ^NurMP.NurEmrSubLock("Mp",code)
		}	

	}

	q 0

